use serde::{Deserialize, Serialize};
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Bank { pub savings: u64, pub loan: u64, #[serde(default)] pub last_interest_day: i64 }
impl Default for Bank { fn default() -> Self { Self { savings: 0, loan: 0, last_interest_day: 0 } } }
#[allow(dead_code)] impl Bank { pub fn interest(&mut self, days: u64) { self.savings = self.savings.saturating_add((self.savings / 100).min(10_000) * days); self.loan = self.loan.saturating_add((self.loan / 10) * days); } #[allow(dead_code)] pub fn deposit(&mut self, chips: &mut u64, amount: u64) -> bool { if amount <= *chips { *chips -= amount; self.savings += amount; true } else { false } } pub fn withdraw(&mut self, chips: &mut u64, amount: u64) -> bool { if self.loan == 0 && amount <= self.savings { self.savings -= amount; *chips += amount; true } else { false } } #[allow(dead_code)] pub fn borrow(&mut self, chips: &mut u64, amount: u64, level: u32) -> bool { let max = level as u64 * 5_000; if self.loan + amount <= max { self.loan += amount; *chips += amount; true } else { false } } }
#[cfg(test)] mod tests { use super::*; #[test] fn interest() { let mut b = Bank { savings: 1000, loan: 1000, last_interest_day: 0 }; b.interest(1); assert_eq!(b.savings, 1010); assert_eq!(b.loan, 1100); } #[test] fn loan_blocks_withdrawal() { let mut b = Bank { savings: 100, loan: 1, last_interest_day: 0 }; let mut c = 0; assert!(!b.withdraw(&mut c, 100)); } }
